<?php if ($total):?><div class="table-pagination"><div>Showing <?= number_format($offset + 1)?>–<?= number_format(min($offset + $per, $total))?> of <?= number_format($total)?></div><div class="pagination-actions"><?php $pageQuery = $_GET;
    $pageQuery['tab'] = $activeTab;
    if ($page > 1):$pageQuery['page'] = $page - 1;?><a class="btn btn-sm btn-outline-secondary" href="<?= ecEscape($advancePage)?>?<?= ecEscape(http_build_query($pageQuery))?>"><i class="bi bi-chevron-left"></i> Previous</a><?php endif;?><span>Page <?= number_format($page)?> of <?= number_format($pages)?></span><?php if ($page < $pages):$pageQuery['page'] = $page + 1;?><a class="btn btn-sm btn-outline-secondary" href="<?= ecEscape($advancePage)?>?<?= ecEscape(http_build_query($pageQuery))?>">Next <i class="bi bi-chevron-right"></i></a><?php endif;?></div></div><?php endif;?>
